import { useEffect, useRef, useState } from 'react';
import { Menu as MenuIcon, X } from 'lucide-react';
import Faq from './components/Faq';

// Domain design tokens (resolved server-side by the design system).
const tw = {"page_bg": "bg-[#faf6f0]", "surface": "bg-white", "surface_2": "bg-[#f3ece2]", "heading_text": "text-stone-900", "body_text": "text-stone-600", "muted_text": "text-stone-500", "primary": "bg-amber-800", "primary_hover": "hover:bg-amber-900", "on_primary": "text-amber-50", "border": "border-stone-200", "accent_text": "text-amber-800", "accent_bg": "bg-amber-100", "gradient": "from-amber-700 to-orange-800"};
const RADIUS = "rounded-2xl";
const GRAD = "bg-gradient-to-br from-amber-700 to-orange-800";
const FONT_CSS = ".font-display{font-family: 'Playfair Display', Georgia, serif;} .font-body{font-family: 'Inter', system-ui, sans-serif;} body{font-family: 'Inter', system-ui, sans-serif;}";
const LOGO_URL = "";

// Scroll-reveal wrapper: sections animate in as they enter the viewport
// (IntersectionObserver; no-ops during server render).
function Reveal({ children }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return undefined;
    const io = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) { setVisible(true); io.disconnect(); }
    }, { threshold: 0.12 });
    io.observe(el);
    // Fallback: embedded/short viewports may never fire the observer
    // (live: preview iframes without scroll) -- never leave content invisible.
    const t = setTimeout(() => { setVisible(true); io.disconnect(); }, 1200);
    return () => { clearTimeout(t); io.disconnect(); };
  }, []);
  return (
    <div ref={ref} className={`reveal ${visible ? 'reveal-visible' : ''}`}>{children}</div>
  );
}

export default function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  const links = [
    { label: "FAQ", href: "#faq" },
  ];
  return (
    <div className={`min-h-screen ${tw.page_bg} ${tw.heading_text} font-body`}>
      <style>{FONT_CSS}</style>
      <header className={`sticky top-0 z-50 backdrop-blur-xl border-b ${tw.page_bg} ${tw.border}`}>
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <a href="#top" className="flex items-center gap-2">
            {LOGO_URL ? (
              <img src="" alt="Casa Verde" className="h-9 w-auto" />
            ) : (
              <span className={`w-9 h-9 ${GRAD} flex items-center justify-center ${tw.on_primary} font-black text-sm tracking-tight ${RADIUS}`}>CV</span>
            )}
            <span className="font-display font-extrabold text-lg tracking-tight">Casa Verde</span>
          </a>
          <nav className={`hidden md:flex items-center gap-8 text-sm font-medium ${tw.body_text}`}>
            {links.map(l => <a key={l.href} href={l.href} className="hover:opacity-70 transition-opacity">{l.label}</a>)}
          </nav>
          <div className="hidden md:flex items-center gap-3">
            <a href="#top" className={`px-4 py-2 ${tw.primary} ${tw.primary_hover} ${tw.on_primary} text-sm font-semibold ${RADIUS} transition-colors`}>Get started</a>
          </div>
          <button className="md:hidden p-2" onClick={() => setMenuOpen(!menuOpen)} aria-label="Menu">
            {menuOpen ? <X className="w-5 h-5" /> : <MenuIcon className="w-5 h-5" />}
          </button>
        </div>
        {menuOpen && (
          <div className={`md:hidden border-t px-6 py-4 space-y-3 ${tw.surface} ${tw.border}`}>
            {links.map(l => <a key={l.href} href={l.href} onClick={() => setMenuOpen(false)} className={`block font-medium ${tw.body_text}`}>{l.label}</a>)}
            <a href="#top" className={`block text-center px-4 py-2.5 ${tw.primary} ${tw.on_primary} font-semibold ${RADIUS}`}>Get started</a>
          </div>
        )}
      </header>
      <main id="top">
      <Reveal><Faq /></Reveal>
      </main>
      <footer className={`border-t py-10 text-center text-sm ${tw.border} ${tw.muted_text}`}>
        <div className="flex items-center justify-center gap-2 mb-2">
          {LOGO_URL ? (
            <img src="" alt="Casa Verde" className="h-7 w-auto" />
          ) : (
            <span className={`w-7 h-7 ${GRAD} flex items-center justify-center ${tw.on_primary} font-black text-[11px] ${RADIUS}`}>CV</span>
          )}
          <span className="font-display font-bold">Casa Verde</span>
        </div>
        &copy; 2026 Casa Verde. All rights reserved.
      </footer>
    </div>    );
}

import React, { useState } from 'react';
import { Sparkles, ChevronRight, CheckCircle2, X } from 'lucide-react';

const initialFaq = [
  {
    id: 1,
    question: 'Do you offer delivery?',
    answer: 'Currently, we focus on dine-in experiences, but we are exploring delivery options for our most loyal customers.',
    isOpen: false,
  },
  {
    id: 2,
    question: 'What types of wine do you serve?',
    answer: 'We pride ourselves on a curated selection of natural and organic wines from small producers across Italy and the Mediterranean.',
    isOpen: false,
  },
  {
    id: 3,
    question: 'Can I bring my own bottle?',
    answer: 'Yes, we welcome guests to bring their own bottle for corkage. Please inform us ahead of your reservation.',
    isOpen: false,
  },
  {
    id: 4,
    question: 'Do you accommodate dietary restrictions?',
    answer: 'Absolutely! We work with many guests with special dietary needs. Please let us know in advance so we can tailor the menu.',
    isOpen: false,
  },
  {
    id: 5,
    question: 'What time is last call?',
    answer: 'Last call is at 10:00 PM. We aim to create a cozy atmosphere that extends into the evening, but we respect all our guests.',
    isOpen: false,
  },
];

export default function Faq() {
  const [currentFaq, setCurrentFaq] = useState(initialFaq);

  const toggleAccordion = (id) => {
    setCurrentFaq((prev) =>
      prev.map((faq) => {
        if (faq.id === id) {
          return { ...faq, isOpen: !faq.isOpen };
        }
        return faq;
      })
    );
  };

  return (
    <div className="w-full max-w-6xl mx-auto p-6 sm:p-10 bg-amber-900 text-stone-600">
      <div className="mb-12 text-center">
        <h2 className="text-2xl sm:text-3xl font-bold tracking-tight text-amber-400">
          Frequently Asked Questions
        </h2>
        <p className="mt-4 text-stone-600 max-w-md mx-auto">
          Here are some common questions and answers to help you plan your visit.
        </p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {currentFaq.map((faq) => (
          <div
            key={faq.id}
            className="group relative rounded-2xl bg-[#f3ece2] backdrop-blur-xl border border-stone-200 p-6 transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl hover:shadow-amber/30"
          >
            <div className="absolute -inset-0.5 bg-[#f3ece2] rounded-2xl border border-stone-200" />
            <div className="flex justify-between items-start mb-6">
              <div className="flex items-center gap-3 text-stone-600">
                <Sparkles className="w-5 h-5 text-amber-400" />
                {faq.question}
              </div>
              <button
                onClick={() => toggleAccordion(faq.id)}
                className="p-2 rounded-lg text-stone-500 hover:text-stone-600 transition-colors"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>
            {faq.isOpen && (
              <div className="text-stone-600 max-w-md">
                <p className="mt-4">{faq.answer}</p>
                <div className="flex items-center justify-between mt-6">
                  <div className="flex items-center gap-2">
                    <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                    <span>Got it!</span>
                  </div>
                  <button
                    onClick={() => toggleAccordion(faq.id)}
                    className="text-stone-500 hover:text-stone-600 transition-colors"
                  >
                    <X className="w-5 h-5" />
                  </button>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

.font-display { font-family: 'Playfair Display', Georgia, serif; }
.font-body { font-family: 'Inter', system-ui, sans-serif; }
body { font-family: 'Inter', system-ui, sans-serif; }

@keyframes reveal-up { from { opacity: 0; transform: translateY(28px); } to { opacity: 1; transform: translateY(0); } }
.reveal { opacity: 0; }
.reveal-visible { animation: reveal-up 0.8s cubic-bezier(0.22, 1, 0.36, 1) both; }
@media (prefers-reduced-motion: reduce) {
  .reveal { opacity: 1; }
  .reveal-visible { animation: none; }
}
@keyframes fade-up { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: translateY(0); } }
.animate-fade-up { animation: fade-up 0.7s ease-out both; }
@keyframes float-slow { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
.animate-float-slow { animation: float-slow 5s ease-in-out infinite; }
@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }
.animate-marquee { animation: marquee 30s linear infinite; }

import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
